def S(n):
    s = 0
    while n:
        s += n % 10
        n //= 10
    return s

def check_condition(n):
    for k in range(38):
        if S(n + k) % 11 == 0:
            return False
    return True

for n in range(1, 1000000):
    if check_condition(n):
        print(n)
        break

